const block = ($json.content ?? []).find((b) => b.type === 'tool_use' && b.name === 'record_official_releases');
const releases = block?.input?.releases;
if (!Array.isArray(releases) || releases.length === 0) return [];

const allowed = new Set(['openai.com','www.openai.com','developers.openai.com','anthropic.com','www.anthropic.com','blog.google','deepmind.google','ai.google.dev','ai.meta.com','x.ai','www.x.ai','deepseek.com','www.deepseek.com','qwen.ai','www.qwen.ai','qwencloud.com','www.qwencloud.com','alibabacloud.com','www.alibabacloud.com','z.ai','www.z.ai','moonshot.ai','www.moonshot.ai','kimi.com','www.kimi.com','minimax.io','www.minimax.io','sakana.ai','www.sakana.ai']);
const models = [];
for (const r of releases.slice(0, 30)) {
  let url;
  try { url = new URL(String(r.announcementUrl ?? '')); } catch { continue; }
  if (url.protocol !== 'https:' || !allowed.has(url.hostname.toLowerCase())) continue;
  const actualDate = String(r.actualDate ?? '').trim();
  const slug = String(r.slug ?? '').trim().toLowerCase();
  const name = String(r.name ?? '').trim();
  const provider = String(r.provider ?? '').trim();
  const providerBlurb = String(r.providerBlurb ?? '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(actualDate) || !/^[a-z0-9-]+$/.test(slug)) continue;
  if (!name || !provider || providerBlurb.length < 20) continue;
  models.push({ name, slug, provider, status: 'released', actualDate, announcementUrl: url.toString(), providerBlurb: providerBlurb.slice(0, 2000), summaryIsAutoDrafted: true });
}
return models.length ? [{ json: { models } }] : [];
